fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    assert!(len > 0, "input array must be non-empty");

    let r = n % len;         // effective right rotation
    let s = (len - r) % len; // start index of the suffix to move to front

    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..]);
    new_list.extend_from_slice(&list[..s]);
    new_list
}